def gen(rng):
    def fmt(cap, ops):
        return str(cap) + '\n' + str(len(ops)) + '\n' + '\n'.join(ops)
    def rnd_ops(q, keyspace, vmax, pget, hot=None):
        ops = []
        for _ in range(q):
            if hot and rng.random() < 0.8:
                k = rng.randint(0, hot)
            else:
                k = rng.randint(0, keyspace)
            if rng.random() < pget:
                ops.append('get ' + str(k))
            else:
                ops.append('put ' + str(k) + ' ' + str(rng.randint(0, vmax)))
        return ops
    tests = [
        fmt(1, ['put 1 1', 'get 1']),
        fmt(0, ['put 1 1', 'get 1', 'get 2']),
        fmt(1, ['get 7', 'put 7 9', 'put 7 8', 'get 7', 'put 8 1', 'get 7', 'get 8']),
